#!/usr/bin/env bash
set -euo pipefail

# verify.sh for go-rename-002 — generated by eval/gen.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR/repo"

go vet ./...
grep -qw "calculateChecksum" main.go

if grep -qw "computeChecksum" main.go; then
  echo "FAIL: computeChecksum still present in main.go" >&2
  exit 1
fi

echo "PASS: go-rename-002"
